import type { SQLiteDatabase } from 'expo-sqlite';

const VERSI_DB = 1;

// Dipanggil sekali oleh SQLiteProvider saat aplikasi dibuka.
export async function migrateDb(db: SQLiteDatabase) {
  const baris = await db.getFirstAsync<{ user_version: number }>('PRAGMA user_version');
  const versi = baris?.user_version ?? 0;
  if (versi >= VERSI_DB) return;

  if (versi === 0) {
    await db.execAsync(`
      PRAGMA journal_mode = WAL;
      CREATE TABLE IF NOT EXISTS transaksi (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        jenis TEXT NOT NULL CHECK (jenis IN ('masuk', 'keluar')),
        jumlah INTEGER NOT NULL CHECK (jumlah > 0),
        kategori TEXT NOT NULL,
        catatan TEXT NOT NULL DEFAULT '',
        tanggal TEXT NOT NULL,
        dibuat TEXT NOT NULL DEFAULT (datetime('now'))
      );
      CREATE INDEX IF NOT EXISTS idx_transaksi_tanggal ON transaksi (tanggal);
    `);
  }
  // Perubahan tabel berikutnya: tambah blok if (versi < 2) { ... } dan naikkan VERSI_DB.
  await db.execAsync(`PRAGMA user_version = ${VERSI_DB}`);
}

