import { useEffect, useState } from 'react';
import { Text, View } from 'react-native';
import { Stack } from 'expo-router';
import { useSQLiteContext } from 'expo-sqlite';

export default function Beranda() {
  const db = useSQLiteContext();
  const [versi, setVersi] = useState('...');

  useEffect(() => {
    db.getFirstAsync<{ v: string }>('SELECT sqlite_version() AS v').then((r) => setVersi(r?.v ?? '?'));
  }, [db]);

  return (
    <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
      <Stack.Screen options={{ title: 'Uangku' }} />
      <Text>SQLite {versi} siap dipakai.</Text>
    </View>
  );
}

export type Jenis = 'masuk' | 'keluar';

export type Transaksi = {
  id: number;
  jenis: Jenis;
  jumlah: number; // rupiah utuh, tanpa sen
  kategori: string;
  catatan: string;
  tanggal: string; // TTTT-BB-HH
};

export type FormTransaksi = {
  jenis: Jenis;
  jumlah: string;
  kategori: string;
  tanggal: string;
  catatan: string;
};

export type Galat = Partial<Record<keyof FormTransaksi, string>>;

export const KATEGORI: Record<Jenis, string[]> = {
  keluar: ['Makan', 'Transport', 'Belanja', 'Tagihan', 'Hiburan', 'Lainnya'],
  masuk: ['Gaji', 'Uang saku', 'Freelance', 'Lainnya'],
};

const formatRupiah = new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  minimumFractionDigits: 0,
  maximumFractionDigits: 0,
});

export const rupiah = (n: number) => formatRupiah.format(n);

const dua = (n: number) => String(n).padStart(2, '0');

export const keTanggal = (d: Date) =>
  `${d.getFullYear()}-${dua(d.getMonth() + 1)}-${dua(d.getDate())}`;

export const hariIni = () => keTanggal(new Date());
export const bulanIni = () => hariIni().slice(0, 7);

function keDate(tanggal: string) {
  const [t, b, h] = tanggal.split('-').map(Number);
  return new Date(t, b - 1, h || 1);
}

// Tanggal valid kalau bolak-balik Date tetap sama: 2026-02-30 akan jadi 2026-03-02.
export function tanggalValid(s: string) {
  return /^\d{4}-\d{2}-\d{2}$/.test(s) && keTanggal(keDate(s)) === s;
}

export const geserBulan = (bulan: string, n: number) => {
  const d = keDate(bulan);
  return keTanggal(new Date(d.getFullYear(), d.getMonth() + n, 1)).slice(0, 7);
};

// Tanggal disimpan sebagai teks TTTT-BB-HH, jadi perbandingan teks sama dengan urutan waktu.
export const rentangBulan = (bulan: string): [string, string] => [`${bulan}-01`, `${bulan}-31`];

export const labelBulan = (bulan: string) =>
  keDate(bulan).toLocaleDateString('id-ID', { month: 'long', year: 'numeric' });

export const labelHari = (tanggal: string) =>
  keDate(tanggal).toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' });

export function totalBulan(daftar: Transaksi[]) {
  let masuk = 0;
  let keluar = 0;
  for (const t of daftar) {
    if (t.jenis === 'masuk') masuk += t.jumlah;
    else keluar += t.jumlah;
  }
  return { masuk, keluar };
}

// Daftar sudah urut tanggal turun dari database, jadi cukup dipotong tiap ganti tanggal.
export function kelompokkanPerHari(daftar: Transaksi[]) {
  const grup: { title: string; data: Transaksi[] }[] = [];
  for (const t of daftar) {
    const akhir = grup[grup.length - 1];
    if (akhir && akhir.title === t.tanggal) akhir.data.push(t);
    else grup.push({ title: t.tanggal, data: [t] });
  }
  return grup;
}

export function validasi(
  f: FormTransaksi,
): { ok: true; data: Omit<Transaksi, 'id'> } | { ok: false; galat: Galat } {
  const galat: Galat = {};
  const angka = Number(f.jumlah.replace(/[.\s]/g, ''));

  if (!f.jumlah.trim()) galat.jumlah = 'Isi jumlahnya.';
  else if (!Number.isInteger(angka) || angka <= 0) galat.jumlah = 'Jumlah harus angka bulat lebih dari 0.';
  else if (angka > 1_000_000_000_000) galat.jumlah = 'Jumlahnya terlalu besar.';

  if (!KATEGORI[f.jenis].includes(f.kategori)) galat.kategori = 'Pilih salah satu kategori.';

  if (!tanggalValid(f.tanggal)) galat.tanggal = 'Tulis tanggal dengan format TTTT-BB-HH, misalnya 2026-11-26.';
  else if (f.tanggal > hariIni()) galat.tanggal = 'Tanggal tidak boleh di masa depan.';

  if (f.catatan.length > 100) galat.catatan = 'Catatan paling panjang 100 karakter.';

  if (Object.keys(galat).length > 0) return { ok: false, galat };
  return {
    ok: true,
    data: { jenis: f.jenis, jumlah: angka, kategori: f.kategori, catatan: f.catatan.trim(), tanggal: f.tanggal },
  };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { geserBulan, kelompokkanPerHari, rupiah, tanggalValid, totalBulan, validasi } from '../lib/uang.ts';

const form = { jenis: 'keluar', jumlah: '15.000', kategori: 'Makan', tanggal: '2026-01-05', catatan: ' bakso ' };

test('rupiah memakai titik sebagai pemisah ribuan', () => {
  assert.equal(rupiah(1250000).replace(/\s/g, ' '), 'Rp 1.250.000');
});

test('tanggal tidak nyata ditolak', () => {
  assert.equal(tanggalValid('2026-02-28'), true);
  assert.equal(tanggalValid('2026-02-30'), false);
  assert.equal(tanggalValid('26-2-1'), false);
});

test('geser bulan melewati pergantian tahun', () => {
  assert.equal(geserBulan('2026-12', 1), '2027-01');
  assert.equal(geserBulan('2026-01', -1), '2025-12');
});

test('validasi menerima form benar dan merapikan isinya', () => {
  const hasil = validasi(form);
  assert.equal(hasil.ok, true);
  assert.equal(hasil.data.jumlah, 15000);
  assert.equal(hasil.data.catatan, 'bakso');
});

test('validasi menolak jumlah, kategori, dan tanggal yang salah', () => {
  const hasil = validasi({ ...form, jumlah: '12,5', kategori: 'Gaji', tanggal: '2999-01-01' });
  assert.equal(hasil.ok, false);
  assert.deepEqual(Object.keys(hasil.galat).sort(), ['jumlah', 'kategori', 'tanggal']);
});

test('total dan kelompok per hari', () => {
  const daftar = [
    { id: 3, jenis: 'keluar', jumlah: 20000, kategori: 'Makan', catatan: '', tanggal: '2026-01-05' },
    { id: 2, jenis: 'masuk', jumlah: 500000, kategori: 'Gaji', catatan: '', tanggal: '2026-01-05' },
    { id: 1, jenis: 'keluar', jumlah: 5000, kategori: 'Transport', catatan: '', tanggal: '2026-01-04' },
  ];
  assert.deepEqual(totalBulan(daftar), { masuk: 500000, keluar: 25000 });
  assert.deepEqual(kelompokkanPerHari(daftar).map((g) => [g.title, g.data.length]), [['2026-01-05', 2], ['2026-01-04', 1]]);
});

// 1) Tambahkan di bawah baris import yang sudah ada di lib/db.ts:
import { rentangBulan, type Jenis, type Transaksi } from './uang';

// 2) Tambahkan di bagian paling bawah lib/db.ts:
export function tambahTransaksi(db: SQLiteDatabase, t: Omit<Transaksi, 'id'>) {
  return db.runAsync(
    'INSERT INTO transaksi (jenis, jumlah, kategori, catatan, tanggal) VALUES (?, ?, ?, ?, ?)',
    t.jenis,
    t.jumlah,
    t.kategori,
    t.catatan,
    t.tanggal,
  );
}

import { useState } from 'react';
import { Alert, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { router, Stack } from 'expo-router';
import { useSQLiteContext } from 'expo-sqlite';
import { tambahTransaksi } from '../lib/db';
import { KATEGORI, hariIni, validasi, type FormTransaksi, type Galat, type Jenis } from '../lib/uang';

export default function Tambah() {
  const db = useSQLiteContext();
  const [form, setForm] = useState<FormTransaksi>({
    jenis: 'keluar',
    jumlah: '',
    kategori: '',
    tanggal: hariIni(),
    catatan: '',
  });
  const [galat, setGalat] = useState<Galat>({});
  const [menyimpan, setMenyimpan] = useState(false);

  const ubah = (kolom: 'jumlah' | 'kategori' | 'tanggal' | 'catatan', nilai: string) =>
    setForm((f) => ({ ...f, [kolom]: nilai }));

  const gantiJenis = (jenis: Jenis) => setForm((f) => ({ ...f, jenis, kategori: '' }));

  async function simpan() {
    const hasil = validasi(form);
    if (!hasil.ok) {
      setGalat(hasil.galat);
      return;
    }
    setMenyimpan(true);
    try {
      await tambahTransaksi(db, hasil.data);
      router.back();
    } catch (e) {
      setMenyimpan(false);
      Alert.alert('Gagal menyimpan', e instanceof Error ? e.message : String(e));
    }
  }

  return (
    <ScrollView contentContainerStyle={s.layar} keyboardShouldPersistTaps="handled">
      <Stack.Screen options={{ title: 'Catat transaksi' }} />

      <View style={s.baris}>
        {(['keluar', 'masuk'] as const).map((j) => (
          <Pressable
            key={j}
            onPress={() => gantiJenis(j)}
            style={[s.chip, form.jenis === j && s.chipAktif]}
            accessibilityRole="button"
            accessibilityState={{ selected: form.jenis === j }}
          >
            <Text style={form.jenis === j ? s.chipTeksAktif : undefined}>
              {j === 'keluar' ? 'Pengeluaran' : 'Pemasukan'}
            </Text>
          </Pressable>
        ))}
      </View>

      <Text style={s.label}>Jumlah (Rp)</Text>
      <TextInput
        style={s.input}
        value={form.jumlah}
        onChangeText={(v) => ubah('jumlah', v)}
        keyboardType="number-pad"
        placeholder="15000"
      />
      {galat.jumlah ? <Text style={s.galat}>{galat.jumlah}</Text> : null}

      <Text style={s.label}>Kategori</Text>
      <View style={[s.baris, s.bungkus]}>
        {KATEGORI[form.jenis].map((k) => (
          <Pressable
            key={k}
            onPress={() => ubah('kategori', k)}
            style={[s.chip, form.kategori === k && s.chipAktif]}
            accessibilityRole="button"
            accessibilityState={{ selected: form.kategori === k }}
          >
            <Text style={form.kategori === k ? s.chipTeksAktif : undefined}>{k}</Text>
          </Pressable>
        ))}
      </View>
      {galat.kategori ? <Text style={s.galat}>{galat.kategori}</Text> : null}

      <Text style={s.label}>Tanggal (TTTT-BB-HH)</Text>
      <TextInput
        style={s.input}
        value={form.tanggal}
        onChangeText={(v) => ubah('tanggal', v)}
        placeholder="2026-11-26"
        maxLength={10}
      />
      {galat.tanggal ? <Text style={s.galat}>{galat.tanggal}</Text> : null}

      <Text style={s.label}>Catatan (opsional)</Text>
      <TextInput
        style={s.input}
        value={form.catatan}
        onChangeText={(v) => ubah('catatan', v)}
        placeholder="Nasi goreng dekat kampus"
        maxLength={100}
      />
      {galat.catatan ? <Text style={s.galat}>{galat.catatan}</Text> : null}

      <Pressable style={[s.tombol, menyimpan && s.redup]} onPress={simpan} disabled={menyimpan}>
        <Text style={s.tombolTeks}>{menyimpan ? 'Menyimpan...' : 'Simpan'}</Text>
      </Pressable>
    </ScrollView>
  );
}

const s = StyleSheet.create({
  layar: { padding: 16, gap: 8 },
  baris: { flexDirection: 'row', gap: 8 },
  bungkus: { flexWrap: 'wrap' },
  chip: { paddingVertical: 8, paddingHorizontal: 14, borderRadius: 999, borderWidth: 1, borderColor: '#c9ccc4' },
  chipAktif: { backgroundColor: '#1b1d1a', borderColor: '#1b1d1a' },
  chipTeksAktif: { color: '#fff' },
  label: { marginTop: 12, fontWeight: '600' },
  input: { borderWidth: 1, borderColor: '#c9ccc4', borderRadius: 10, padding: 12, fontSize: 16 },
  galat: { color: '#b3261e' },
  tombol: { marginTop: 24, backgroundColor: '#1b1d1a', borderRadius: 12, padding: 16, alignItems: 'center' },
  redup: { opacity: 0.5 },
  tombolTeks: { color: '#fff', fontWeight: '700', fontSize: 16 },
});

// Tambahkan di bagian paling bawah lib/db.ts.
export function transaksiBulan(db: SQLiteDatabase, bulan: string) {
  const [awal, akhir] = rentangBulan(bulan);
  return db.getAllAsync<Transaksi>(
    `SELECT id, jenis, jumlah, kategori, catatan, tanggal
     FROM transaksi
     WHERE tanggal BETWEEN ? AND ?
     ORDER BY tanggal DESC, id DESC`,
    awal,
    akhir,
  );
}

// Saldo = semua pemasukan dikurangi semua pengeluaran sampai akhir bulan itu.
export async function saldoSampai(db: SQLiteDatabase, bulan: string) {
  const baris = await db.getFirstAsync<{ saldo: number }>(
    `SELECT COALESCE(SUM(CASE WHEN jenis = 'masuk' THEN jumlah ELSE -jumlah END), 0) AS saldo
     FROM transaksi
     WHERE tanggal <= ?`,
    rentangBulan(bulan)[1],
  );
  return baris?.saldo ?? 0;
}

export function hapusTransaksi(db: SQLiteDatabase, id: number) {
  return db.runAsync('DELETE FROM transaksi WHERE id = ?', id);
}

import { useCallback, useState } from 'react';
import { Alert, Pressable, SectionList, StyleSheet, Text, View } from 'react-native';
import { Link, Stack, useFocusEffect } from 'expo-router';
import { useSQLiteContext } from 'expo-sqlite';
import { hapusTransaksi, saldoSampai, transaksiBulan } from '../lib/db';
import {
  bulanIni,
  geserBulan,
  kelompokkanPerHari,
  labelBulan,
  labelHari,
  rupiah,
  totalBulan,
  type Transaksi,
} from '../lib/uang';

export default function Beranda() {
  const db = useSQLiteContext();
  const [bulan, setBulan] = useState(bulanIni);
  const [daftar, setDaftar] = useState<Transaksi[]>([]);
  const [saldo, setSaldo] = useState(0);

  const muat = useCallback(async () => {
    setDaftar(await transaksiBulan(db, bulan));
    setSaldo(await saldoSampai(db, bulan));
  }, [db, bulan]);

  // Dipanggil setiap layar ini tampil lagi, misalnya setelah kembali dari form.
  useFocusEffect(
    useCallback(() => {
      muat();
    }, [muat]),
  );

  function konfirmasiHapus(t: Transaksi) {
    Alert.alert('Hapus transaksi?', `${t.kategori} ${rupiah(t.jumlah)}`, [
      { text: 'Batal', style: 'cancel' },
      {
        text: 'Hapus',
        style: 'destructive',
        onPress: async () => {
          await hapusTransaksi(db, t.id);
          muat();
        },
      },
    ]);
  }

  const { masuk, keluar } = totalBulan(daftar);

  return (
    <View style={s.layar}>
      <Stack.Screen options={{ title: 'Uangku' }} />

      <View style={s.navBulan}>
        <Pressable onPress={() => setBulan(geserBulan(bulan, -1))} hitSlop={12} accessibilityLabel="Bulan sebelumnya">
          <Text style={s.panah}>‹</Text>
        </Pressable>
        <Text style={s.judulBulan}>{labelBulan(bulan)}</Text>
        <Pressable onPress={() => setBulan(geserBulan(bulan, 1))} hitSlop={12} accessibilityLabel="Bulan berikutnya">
          <Text style={s.panah}>›</Text>
        </Pressable>
      </View>

      <View style={s.kartu}>
        <Text style={s.kecil}>Saldo sampai akhir bulan</Text>
        <Text style={s.saldo}>{rupiah(saldo)}</Text>
        <View style={s.baris}>
          <Text style={s.masuk}>Masuk {rupiah(masuk)}</Text>
          <Text style={s.keluar}>Keluar {rupiah(keluar)}</Text>
        </View>
        <Link href={{ pathname: '/ringkasan', params: { bulan } }} style={s.tautan}>
          Lihat per kategori
        </Link>
      </View>

      <SectionList
        sections={kelompokkanPerHari(daftar)}
        keyExtractor={(t) => String(t.id)}
        renderSectionHeader={({ section }) => <Text style={s.hari}>{labelHari(section.title)}</Text>}
        renderItem={({ item }) => (
          <Pressable onLongPress={() => konfirmasiHapus(item)} style={s.item}>
            <View style={s.isi}>
              <Text style={s.kategori}>{item.kategori}</Text>
              {item.catatan ? <Text style={s.kecil}>{item.catatan}</Text> : null}
            </View>
            <Text style={item.jenis === 'masuk' ? s.masuk : s.keluar}>
              {item.jenis === 'masuk' ? '+' : '-'}
              {rupiah(item.jumlah)}
            </Text>
          </Pressable>
        )}
        ListEmptyComponent={<Text style={s.kosong}>Belum ada transaksi di bulan ini.</Text>}
        contentContainerStyle={s.daftar}
      />

      <Link href="/tambah" asChild>
        <Pressable style={s.fab} accessibilityLabel="Catat transaksi">
          <Text style={s.fabTeks}>+</Text>
        </Pressable>
      </Link>
    </View>
  );
}

const s = StyleSheet.create({
  layar: { flex: 1, backgroundColor: '#f6f7f2' },
  navBulan: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', padding: 16 },
  panah: { fontSize: 28, paddingHorizontal: 8 },
  judulBulan: { fontSize: 18, fontWeight: '700' },
  kartu: { marginHorizontal: 16, padding: 16, borderRadius: 16, backgroundColor: '#fff', gap: 6 },
  saldo: { fontSize: 28, fontWeight: '800' },
  baris: { flexDirection: 'row', justifyContent: 'space-between' },
  masuk: { color: '#1f6f4a', fontWeight: '600' },
  keluar: { color: '#b3261e', fontWeight: '600' },
  tautan: { marginTop: 6, color: '#1f6f4a', fontWeight: '600' },
  daftar: { padding: 16, paddingBottom: 96 },
  hari: { marginTop: 12, marginBottom: 4, fontWeight: '700', color: '#55594f' },
  item: { flexDirection: 'row', alignItems: 'center', padding: 12, borderRadius: 12, backgroundColor: '#fff', marginBottom: 6 },
  isi: { flex: 1 },
  kategori: { fontWeight: '600' },
  kecil: { color: '#55594f' },
  kosong: { textAlign: 'center', marginTop: 32, color: '#55594f' },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 60,
    height: 60,
    borderRadius: 30,
    backgroundColor: '#1b1d1a',
    alignItems: 'center',
    justifyContent: 'center',
  },
  fabTeks: { color: '#fff', fontSize: 30, lineHeight: 32 },
});

// Tambahkan di bagian paling bawah lib/db.ts.
export type BarisKategori = { kategori: string; total: number; banyak: number };

export function ringkasanKategori(db: SQLiteDatabase, bulan: string, jenis: Jenis) {
  const [awal, akhir] = rentangBulan(bulan);
  return db.getAllAsync<BarisKategori>(
    `SELECT kategori, SUM(jumlah) AS total, COUNT(*) AS banyak
     FROM transaksi
     WHERE jenis = ? AND tanggal BETWEEN ? AND ?
     GROUP BY kategori
     ORDER BY total DESC`,
    jenis,
    awal,
    akhir,
  );
}

import { useEffect, useState } from 'react';
import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';
import { Stack, useLocalSearchParams } from 'expo-router';
import { useSQLiteContext } from 'expo-sqlite';
import { ringkasanKategori, type BarisKategori } from '../lib/db';
import { bulanIni, labelBulan, rupiah, type Jenis } from '../lib/uang';

export default function Ringkasan() {
  const db = useSQLiteContext();
  const { bulan = bulanIni() } = useLocalSearchParams<{ bulan?: string }>();
  const [jenis, setJenis] = useState<Jenis>('keluar');
  const [baris, setBaris] = useState<BarisKategori[]>([]);

  useEffect(() => {
    ringkasanKategori(db, bulan, jenis).then(setBaris);
  }, [db, bulan, jenis]);

  const total = baris.reduce((a, b) => a + b.total, 0);

  return (
    <View style={s.layar}>
      <Stack.Screen options={{ title: `Ringkasan ${labelBulan(bulan)}` }} />

      <View style={s.tab}>
        {(['keluar', 'masuk'] as const).map((j) => (
          <Pressable
            key={j}
            onPress={() => setJenis(j)}
            style={[s.chip, jenis === j && s.chipAktif]}
            accessibilityRole="button"
            accessibilityState={{ selected: jenis === j }}
          >
            <Text style={jenis === j ? s.chipTeksAktif : undefined}>
              {j === 'keluar' ? 'Pengeluaran' : 'Pemasukan'}
            </Text>
          </Pressable>
        ))}
      </View>

      <Text style={s.total}>Total {rupiah(total)}</Text>

      <FlatList
        data={baris}
        keyExtractor={(b) => b.kategori}
        renderItem={({ item }) => (
          <View style={s.item}>
            <View style={s.atas}>
              <Text style={s.nama}>
                {item.kategori} ({item.banyak}x)
              </Text>
              <Text>
                {rupiah(item.total)} · {Math.round((item.total / total) * 100)}%
              </Text>
            </View>
            <View style={s.batang}>
              <View style={[s.isiBatang, { flex: item.total }]} />
              <View style={{ flex: total - item.total }} />
            </View>
          </View>
        )}
        ListEmptyComponent={<Text style={s.kosong}>Belum ada data di bulan ini.</Text>}
      />
    </View>
  );
}

